   44		if err := json.Unmarshal(data, &f); err != nil {
   45			return nil, fmt.Errorf("store: parse %s: %w", path, err)
   46		}
   47		if f.Version > Version {
   48			return nil, fmt.Errorf("store: file version %d is newer than supported %d", f.Version, Version)
   49		}
   50		for i := range f.Tasks {
   51			t := f.Tasks[i]
   52			s.tasks[t.ID] = &t
   53			if t.ID >= s.nextID {
   54				s.nextID = t.ID + 1
   55			}
   56		}
   57		if f.NextID > s.nextID {
