{"content":"// Package model defines the task type.
package model

import (
	"errors"
	"regexp"
	"sort"
	"strings"
	"time"
)

// Task is one tracked item.
type Task struct {
	ID       int        `json:"id"`
	Title    string     `json:"title"`
	Priority int        `json:"priority"`
	Done     bool       `json:"done"`
	Created  time.Time  `json:"created"`
	Tags     []string   `json:"tags,omitempty"`
	Due      *time.Time `json:"due,omitempty"`
}

// Validation errors.
var (
	ErrEmptyTitle  = errors.New("title must not be empty")
	ErrBadPriority = errors.New("priority must be between 1 and 5")
	ErrBadTag      = errors.New("bad tag")
)

// DefaultPriority is used when none is given.
const DefaultPriority = 3

var tagPattern = regexp.MustCompile(`^[a-z0-9][a-z0-9-]*$`)

// Validate checks the task fields and normalises its tags
// (trimmed, lower-cased, de-duplicated, sorted).
func (t *Task) Validate() error {
	t.Title = strings.TrimSpace(t.Title)
	if t.Title == "" {
		return ErrEmptyTitle
	}
	if t.Priority < 1 || t.Priority > 5 {
		return ErrBadPriority
	}
	seen := make(map[string]bool, len(t.Tags))
	tags := make([]string, 0, len(t.Tags))
	for _, raw := range t.Tags {
		tag := strings.ToLower(strings.TrimSpace(raw))
		if !tagPattern.MatchString(tag) {
			return ErrBadTag
		}
		if seen[tag] {
			continue
		}
		seen[tag] = true
		tags = append(tags, tag)
	}
	sort.Strings(tags)
	t.Tags = tags
	if t.Due != nil {
		t.Due = t.Due.UTC()
	}
	return nil
}
