{"content":"// Package query filters and sorts tasks.
package query

import (
	"fmt"
	"sort"
	"time"

	"example.com/tasker/internal/model"
)

// Options selects and orders tasks.
type Options struct {
	IncludeDone bool
	SortBy      string     // "id" (default), "priority" or "due"
	Tags        []string   // task must have all of these
	Overdue     bool       // only undone tasks due before Today
	Today       time.Time  // UTC midnight of "today"
}

// Apply returns the matching tasks in order.
func Apply(tasks []model.Task, o Options) ([]model.Task, error) {
	var out []model.Task
	for _, t := range tasks {
		if t.Done && !o.IncludeDone {
			continue
		}
		if len(o.Tags) > 0 && !hasAllTags(t, o.Tags) {
			continue
		}
		if o.Overdue {
			if t.Done || t.Due == nil || !t.Due.Before(o.Today) {
				continue
			}
		}
		out = append(out, t)
	}
	switch o.SortBy {
	case "", "id":
		sort.SliceStable(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	case "priority":
		sort.SliceStable(out, func(i, j int) bool {
			if out[i].Priority != out[j].Priority {
				return out[i].Priority < out[j].Priority
			}
			return out[i].ID < out[j].ID
		})
	case "due":
		sort.SliceStable(out, func(i, j int) bool {
			if !dueLess(out[i].Due, out[j].Due) {
				return out[j].Due != nil && !out[j].Due.Before(*out[i].Due)
			}
			return out[i].ID < out[j].ID
		})
	default:
		return nil, fmt.Errorf("unknown sort key %q", o.SortBy)
	}
	return out, nil
}

func hasAllTags(t model.Task, tags []string) bool {
