func dueDate(t *testing.T, s string) *time.Time {
	d, err := time.Parse("2006-01-02", s)
	if err != nil {
		t.Fatal(err)
	}
	d = d.UTC()
	return &d
}

func ids(ts []model.Task) string {
	out := ""
	for _, t := range ts {
		out += string(rune('0' + t.ID))
	}
	return out
}

func TestApplyTags(t *testing.T) {
	d := dueDate(t, "2026-03-01")
	ts := []model.Task{
		{ID: 1, Tags: []string{"home", "money"}, Due: d},
		{ID: 2, Tags: []string{"home", "money"}},
		{ID: 3, Tags: []string{"home"}, Due: dueDate(t, "2026-03-10")},
		{ID: 4, Tags: []string{"money"}, Done: true, Due: dueDate(t, "2026-02-01")},
	}
	got, err := Apply(ts, Options{Tags: []string{"home", "money"}})
	if err != nil || ids(got) != "12" {
		t.Fatalf("got %v err %v, want 12", got, err)
	}
	if got, _ := Apply(ts, Options{Tags: []string{"home"}, IncludeDone: true}); ids(got) != "123" {
		t.Fatalf("want 123, got %v", got)
	}
}

func TestApplyOverdue(t *testing.T) {
	today := time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)
	ts := []model.Task{
		{ID: 1, Due: dueDate(t, "2026-03-01")},
		{ID: 2},
		{ID: 3, Due: dueDate(t, "2026-03-10")}, // due today is not overdue
		{ID: 4, Done: true, Due: dueDate(t, "2026-02-01")},
	}
	got, err := Apply(ts, Options{Overdue: true, Today: today})
	if err != nil || ids(got) != "1" {
		t.Fatalf("got %v err %v, want 1", got, err)
	}
	// even with --all, overdue tasks must be open
	got, _ = Apply(ts, Options{Overdue: true, IncludeDone: true, Today: today})
	if ids(got) != "1" {
		t.Fatalf("got %v, want 1", got)
	}
}

func TestApplySortDue(t *testing.T) {
	ts := []model.Task{
		{ID: 3, Due: dueDate(t, "2026-03-10")},
		{ID: 2},
		{ID: 1, Due: dueDate(t, "2026-03-01")},
		{ID: 4, Due: dueDate(t, "2026-03-01")}, // same due as 1: tie by ID
